import{_ as e,c as s,o as a,aj as t}from"./chunks/framework.BlveriQe.js";const c=JSON.parse('{"title":"Deploying to Production","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/deploying-to-production.md","filePath":"getting-started/deploying-to-production.md"}'),n={name:"getting-started/deploying-to-production.md"};function h(l,i,p,o,r,d){return a(),s("div",null,[...i[0]||(i[0]=[t(`<h1 id="deploying-to-production" tabindex="-1">Deploying to Production <a class="header-anchor" href="#deploying-to-production" aria-label="Permalink to “Deploying to Production”">​</a></h1><p>Each platform ships through its native channel: the web template deploys to Cloudflare Workers, and the iOS template ships through TestFlight and the App Store with Fastlane.</p><h2 id="web-cloudflare-workers" tabindex="-1">Web (Cloudflare Workers) <a class="header-anchor" href="#web-cloudflare-workers" aria-label="Permalink to “Web (Cloudflare Workers)”">​</a></h2><p>The web template deploys to Cloudflare Workers. You&#39;ll need a Cloudflare account with access to deploy Workers.</p><h3 id="_1-configure-wrangler-toml" tabindex="-1">1. Configure wrangler.toml <a class="header-anchor" href="#_1-configure-wrangler-toml" aria-label="Permalink to “1. Configure wrangler.toml”">​</a></h3><p>Edit <code>wrangler.toml</code> to set your worker name:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-app&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">production</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-app-prod&quot;</span></span></code></pre></div><p>By default, your app will be deployed to a <code>*.workers.dev</code> URL. To use a custom domain, uncomment and edit the routes section:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">production</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">routes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-domain.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">custom_domain = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="_2-configure-env-production-app-behavior-only" tabindex="-1">2. Configure .env.production (app behavior only) <a class="header-anchor" href="#_2-configure-env-production-app-behavior-only" aria-label="Permalink to “2. Configure .env.production (app behavior only)”">​</a></h3><p>Edit <code>.env.production</code> with settings that describe how the app behaves:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># OAuth redirect URI for your production domain</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_OAUTH_REDIRECT_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://my-app-prod.your-subdomain.workers.dev/oauth/callback</span></span></code></pre></div><p>The app ID and backend URL are <strong>not</strong> here. They are typed once, in <code>.primitive/config.json</code>, as a named Primitive environment:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://primitiveapi.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app_...</span></span></code></pre></div><p>A deploy refuses to run if it finds <code>VITE_APP_ID</code>, <code>VITE_API_URL</code>, <code>VITE_WS_URL</code> or <code>VITE_APP_NAME</code> in a <code>.env</code> file or in your shell — two sources of truth for the app ID is exactly what that config file removes. (If your app was scaffolded by an older CLI, deleting those lines is the whole migration.)</p><h3 id="_3-deploy" tabindex="-1">3. Deploy <a class="header-anchor" href="#_3-deploy" aria-label="Permalink to “3. Deploy”">​</a></h3><p>A deploy names two independent things, and neither is inferred from the other:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Selects</th><th>Which means</th></tr></thead><tbody><tr><td><code>--deploy-env &lt;name&gt;</code></td><td>the <strong>deploy environment</strong></td><td>the Vite mode (<code>.env.&lt;name&gt;</code>) and the <code>[env.&lt;name&gt;]</code> block in <code>wrangler.toml</code></td></tr><tr><td><code>--primitive-env &lt;name&gt;</code></td><td>the <strong>Primitive environment</strong></td><td>the backend/app pair in <code>.primitive/config.json</code></td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --primitive-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span></span></code></pre></div><p>Omitting either is an error. They cross in practice — a production front end against your alpha backend, or dev and prod builds that both talk to <code>primitiveapi.com</code> with different app IDs:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --primitive-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alpha</span></span></code></pre></div><p>The script prints the resolved pair (deploy environment, Primitive environment, apiUrl, appId, appName, and the config file they came from) before it builds anything. To see that plus the exact build and wrangler commands without running them:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --primitive-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>To pass additional flags to wrangler, use <code>--</code> followed by the flags:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --primitive-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><h3 id="adding-more-environments" tabindex="-1">Adding More Environments <a class="header-anchor" href="#adding-more-environments" aria-label="Permalink to “Adding More Environments”">​</a></h3><p>The two axes grow separately.</p><p><strong>Another deploy environment</strong> (another front end — e.g. a test worker):</p><ol><li>Add a section to <code>wrangler.toml</code>:</li></ol><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-app-test&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REFRESH_PROXY_COOKIE_MAX_AGE = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;604800&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REFRESH_PROXY_COOKIE_PATH = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/proxy/&quot;</span></span></code></pre></div><p>The two <code>vars</code> configure the template&#39;s session refresh proxy: how long its cookie lives (seconds; <code>604800</code> is 7 days) and the path it is scoped to. Copy them as-is from the existing environments.</p><ol start="2"><li><p>Create a corresponding <code>.env.test</code> for app behavior (no identity keys).</p></li><li><p>Deploy it against whichever backend you want:</p></li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --primitive-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span></span></code></pre></div><p><strong>Another Primitive environment</strong> (another backend/app pair):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alpha</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://alpha.primitiveapi.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app_...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deploy-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --primitive-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alpha</span></span></code></pre></div><p>Nothing in <code>wrangler.toml</code> or <code>.env.*</code> changes for a new backend. Name these entries after the backend/app pair they point at — <code>prod</code>, <code>prod-test</code>, <code>alpha</code> — rather than after a build stage, which is the other axis.</p><h3 id="pinning-a-mode-to-a-primitive-environment" tabindex="-1">Pinning a mode to a Primitive environment <a class="header-anchor" href="#pinning-a-mode-to-a-primitive-environment" aria-label="Permalink to “Pinning a mode to a Primitive environment”">​</a></h3><p>The axes crossing freely is usually what you want. It stops being what you want when a mode&#39;s <code>.env</code> keys are only correct against one backend — a per-environment resource ID, a shared database ULID. Then the wrong pairing is silent: the app runs one backend&#39;s identity with another backend&#39;s configuration.</p><p>Say which environment the mode belongs to, in that mode&#39;s file:</p><div class="language-dotenv"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env.production</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">VITE_EXPECTED_PRIMITIVE_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prod</span></span></code></pre></div><p>A run that resolves a different Primitive environment now fails at startup, naming both halves and where each came from. It covers every entry point that resolves one — <code>pnpm dev</code>, <code>pnpm build</code>, <code>pnpm test</code>, and <code>pnpm cf-deploy</code>, which checks the declaration before it builds or prints a <code>--check</code> plan.</p><p>The key is opt-in: without it, nothing changes. A value in the base <code>.env</code> applies to every mode, <code>.env.&lt;mode&gt;</code> overrides it, and an empty value there switches the check off for that mode. To run a cross-wired pair on purpose, state it: <code>VITE_EXPECTED_PRIMITIVE_ENV=dev PRIMITIVE_ENV=dev pnpm test --mode alpha</code>.</p><div class="tip custom-block"><p class="custom-block-title">Pure-env CI builds still work</p><p>A build that supplies both <code>VITE_APP_ID</code> and <code>VITE_API_URL</code> itself resolves no Primitive environment, so there is nothing to check. Setting only one of them does <strong>not</strong> skip the check — the other half still comes from the resolved environment, which is exactly the cross-wire worth catching.</p></div><h2 id="ios-testflight-and-the-app-store" tabindex="-1">iOS (TestFlight and the App Store) <a class="header-anchor" href="#ios-testflight-and-the-app-store" aria-label="Permalink to “iOS (TestFlight and the App Store)”">​</a></h2><p>Simulator builds run unsigned — you need an Apple Developer account ($99/year) and a team ID only for physical devices, TestFlight, and the App Store.</p><h3 id="_1-signing-and-team-id" tabindex="-1">1. Signing and Team ID <a class="header-anchor" href="#_1-signing-and-team-id" aria-label="Permalink to “1. Signing and Team ID”">​</a></h3><ol><li><p>Find your team ID at <a href="https://developer.apple.com/account" target="_blank" rel="noreferrer">developer.apple.com/account</a> → Membership Details (10 characters, e.g. <code>2J4V27W63D</code>).</p></li><li><p>Edit <code>project.yml</code>:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">settings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  base</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    DEVELOPMENT_TEAM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2J4V27W63D&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    CODE_SIGN_STYLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Automatic</span></span></code></pre></div></li><li><p>Regenerate the xcodeproj:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/regenerate-project.sh</span></span></code></pre></div><p>That script is the one entry point for regeneration: it runs <code>xcodegen generate</code> and then re-copies the app&#39;s <code>Package.resolved</code> into the project container xcodegen just rewrote. <code>./run-ios.sh</code>, <code>./archive.sh</code> and the fastlane lanes all call it, so this step is only needed when you want the regeneration on its own. It requires xcodegen (<code>brew install xcodegen</code>) and fails with that instruction if it is missing.</p></li></ol><p>After that, device installs and archives both work.</p><p>With signing set up, <code>./run-ios.sh --device</code> installs directly on a paired iPhone — see <a href="./template-app.html#_2-run-it">Run It</a> on the Quick Start page.</p><h3 id="_2-set-up-fastlane" tabindex="-1">2. Set up Fastlane <a class="header-anchor" href="#_2-set-up-fastlane" aria-label="Permalink to “2. Set up Fastlane”">​</a></h3><p>The iOS template <strong>ships Fastlane</strong> — the project already has a root <code>Gemfile</code>, plus <code>fastlane/Appfile</code>, <code>fastlane/Fastfile</code>, and <code>fastlane/.env.example</code>. That gets you one-command builds to TestFlight and the App Store, plus version bumping. Install the gem:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p><code>fastlane/Appfile</code> is generic — it reads the app identifier and Team ID from <code>project.yml</code> at runtime, so there&#39;s nothing to edit there. Set the Team ID with <code>primitive apple set-team-id &lt;id&gt;</code>, which writes <code>DEVELOPMENT_TEAM</code> in <code>project.yml</code>.</p><h3 id="_3-app-store-connect-api-key" tabindex="-1">3. App Store Connect API Key <a class="header-anchor" href="#_3-app-store-connect-api-key" aria-label="Permalink to “3. App Store Connect API Key”">​</a></h3><p>The lanes below authenticate with App Store Connect using an API key.</p><ol><li><p>Go to <a href="https://appstoreconnect.apple.com/access/integrations/api" target="_blank" rel="noreferrer">App Store Connect → Users and Access → Integrations → App Store Connect API</a>.</p></li><li><p>Create a new key with role <strong>App Manager</strong>.</p></li><li><p>Download the <code>.p8</code> file (you can only download it once) and save it to <code>fastlane/api_key.p8</code>.</p></li><li><p>Note the <strong>Key ID</strong> and <strong>Issuer ID</strong> from the same page.</p></li><li><p>Copy the shipped template and fill in the three values:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastlane/.env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastlane/.env</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># fastlane/.env</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ASC_KEY_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ABC123XYZ</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ASC_ISSUER_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">00000000-0000-0000-0000-000000000000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ASC_KEY_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./fastlane/api_key.p8</span></span></code></pre></div></li></ol><div class="warning custom-block"><p class="custom-block-title">Don&#39;t commit the key</p><p>Add <code>fastlane/api_key.p8</code> and <code>fastlane/.env</code> to <code>.gitignore</code>. The <code>.p8</code> is a private key — leaking it lets anyone upload builds as your team.</p></div><p>If you run a lane before these are set, the Fastfile prints the exact setup steps and stops.</p><h3 id="_4-the-shipped-lanes" tabindex="-1">4. The shipped lanes <a class="header-anchor" href="#_4-the-shipped-lanes" aria-label="Permalink to “4. The shipped lanes”">​</a></h3><p>You don&#39;t write the Fastfile — the template ships it, parameterized off <code>project.yml</code> so it works for any app. List the lanes with <code>bundle exec fastlane lanes</code>:</p><table tabindex="0"><thead><tr><th>Lane</th><th>What it does</th></tr></thead><tbody><tr><td><code>fastlane ios beta</code></td><td>Archive, export, and upload an iOS build to TestFlight</td></tr><tr><td><code>fastlane ios release</code></td><td>Archive, export, and submit an iOS build to App Store review (sets <code>skip_metadata</code> / <code>skip_screenshots</code>)</td></tr><tr><td><code>fastlane mac beta</code></td><td>Upload a macOS build to TestFlight</td></tr><tr><td><code>fastlane mac dmg</code></td><td>Build a notarized DMG for direct distribution</td></tr><tr><td><code>fastlane bump type:patch</code></td><td>Bump the marketing + build version in <code>project.yml</code> and regenerate the xcodeproj (<code>major</code> / <code>minor</code> / <code>patch</code>)</td></tr><tr><td><code>fastlane status</code></td><td>Print the app version, bundle ID, Team ID, signing certificates, and whether the API key is configured</td></tr></tbody></table><p>Each build lane reads the Team ID from <code>project.yml</code> (it stops with the <code>primitive apple set-team-id</code> fix if it&#39;s unset) and loads the API key from <code>fastlane/.env</code>. The lanes export with automatic signing and <code>-allowProvisioningUpdates</code>, so Xcode requests the provisioning profiles for you. Every lane also syncs Xcode&#39;s package pin from the app&#39;s <code>Package.resolved</code> first (see <a href="./template-app.html#updating-the-primitive-packages">Updating the Primitive Packages</a>), so an upload can&#39;t archive against a package revision you&#39;ve already updated past.</p><h3 id="_5-register-the-app-on-app-store-connect" tabindex="-1">5. Register the App on App Store Connect <a class="header-anchor" href="#_5-register-the-app-on-app-store-connect" aria-label="Permalink to “5. Register the App on App Store Connect”">​</a></h3><p>You only do this once per app, before the first upload.</p><ol><li>Go to <a href="https://appstoreconnect.apple.com/apps" target="_blank" rel="noreferrer">App Store Connect → Apps → +</a> → New App.</li><li>Pick <strong>iOS</strong>, set name, primary language, bundle ID (the dropdown shows IDs you&#39;ve registered — if yours is missing, create it at <a href="https://developer.apple.com/account/resources/identifiers/list" target="_blank" rel="noreferrer">developer.apple.com/account/resources/identifiers</a>), SKU (any unique string).</li><li>Choose <strong>Full Access</strong>.</li></ol><h3 id="_6-ship-a-testflight-build" tabindex="-1">6. Ship a TestFlight Build <a class="header-anchor" href="#_6-ship-a-testflight-build" aria-label="Permalink to “6. Ship a TestFlight Build”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastlane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type:patch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # bumps version + build number, regenerates xcodeproj</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastlane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beta</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # archives, exports, uploads</span></span></code></pre></div><p>A first upload takes 10–20 minutes between &quot;Fastlane finished&quot; and the build appearing in TestFlight (Apple processes the binary, runs export compliance, etc.). Subsequent uploads are usually 5 minutes.</p><p>Internal testers (added in the App Store Connect UI under TestFlight) get builds immediately — no separate review. External testers and groups need a one-time Beta App Review per major version.</p><h3 id="_7-submit-to-the-app-store" tabindex="-1">7. Submit to the App Store <a class="header-anchor" href="#_7-submit-to-the-app-store" aria-label="Permalink to “7. Submit to the App Store”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastlane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bump</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type:minor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # if you want to ship a real new version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fastlane</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span></code></pre></div><p><code>upload_to_app_store</code> uploads the binary and submits it for review. The lane above sets <code>skip_metadata: true</code> and <code>skip_screenshots: true</code> — fill those in manually in App Store Connect (description, screenshots, keywords, age rating, privacy answers) before the build can actually be reviewed. Once metadata is complete and the build is processed, the review queue takes 24–72 hours typically.</p><div class="tip custom-block"><p class="custom-block-title">CI</p><p>Both <code>./run-ios.sh</code> and <code>bundle exec fastlane ios beta</code> work in GitHub Actions on a macOS runner. Base64-encode <code>api_key.p8</code> into a secret and decode it before the lane runs.</p></div>`,73)])])}const g=e(n,[["render",h]]);export{c as __pageData,g as default};
